import { assertPositiveCents } from "../../shared/money";

const maxAdvertisingBalanceCents = 75_000_00;

interface AdvertisingAccount {
  ownerId: string;
  balanceCents: number;
  frozen: boolean;
}

const accounts = new Map<string, AdvertisingAccount>();

export function openAdvertisingAccount(id: string, ownerId: string): void {
  accounts.set(id, { ownerId, balanceCents: 0, frozen: false });
}

function activeAdvertisingAccount(id: string): AdvertisingAccount {
  const account = accounts.get(id);
  if (account === undefined || account.frozen) {
    throw new Error(`Unavailable advertising account: ${id}`);
  }
  return account;
}

export function creditAdvertising(id: string, amountCents: number): number {
  assertPositiveCents(amountCents);
  const account = activeAdvertisingAccount(id);
  if (account.balanceCents + amountCents > maxAdvertisingBalanceCents) {
    throw new Error(`Advertising balance cap exceeded: ${id}`);
  }
  account.balanceCents += amountCents;
  return account.balanceCents;
}

export function debitAdvertising(id: string, amountCents: number): number {
  assertPositiveCents(amountCents);
  const account = activeAdvertisingAccount(id);
  if (account.balanceCents < amountCents) {
    throw new Error(`Insufficient advertising balance: ${id}`);
  }
  account.balanceCents -= amountCents;
  return account.balanceCents;
}

export function totalAdvertisingBalanceCents(ownerId: string): number {
  return [...accounts.values()]
    .filter((account) => account.ownerId === ownerId)
    .reduce((total, account) => total + account.balanceCents, 0);
}

